"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[6920],{56920:a=>{a.exports=JSON.parse('{"eyebrow":"Baharu dalam Salat-e-Mustaqeem","lede":"Bacalah, dan halaman mengikut anda. Setiap kalimah menyala keemasan sebaik anda melafazkannya, dan apa yang tertinggal menanti anda di akhir, ditanda dengan lembut.","small":"Percuma. Berfungsi tanpa internet. Suara anda tidak pernah meninggalkan telefon anda.","ctaAppStore":"Muat turun di App Store","ctaPlay":"Dapatkan di Google Play","mushafLabel":"Demonstrasi: Al-F\u0101ti\u1e25ah menyala kalimah demi kalimah semasa dibaca","status":{"listening":"Mendengar\u2026","recited":"Selesai dibaca","review":"Ayat {{n}}: <b>1 kalimah untuk diulang</b>","well":"Ayat {{n}} \xb7 <b>dibaca dengan baik</b>"},"how":{"kicker":"Cara ia berfungsi","h2":"Tiga detik, dan tiada apa antara anda dengan Al-Quran","sub":"Tasm\u012b\u02bf ialah perkataan yang digunakan guru tahfiz untuk \u201cperdengarkan kepada saya\u201d. Ia mendengar seperti guru yang sabar: mengikut, memerhati, dan menunggu.","recite":{"h3":"Bacalah","p":"Buka mana-mana ayat dalam pembaca, atau pelajaran Hifz, dan ketik pelita. Bacalah mengikut rentak anda, seperti anda menyemak bacaan dengan guru."},"follows":{"h3":"Halaman mengikut","p":"Kalimah yang sedang anda baca bercahaya. Halaman berselak sendiri. Apabila ayat tamat, anda nampak apa yang perlu diulang: alun lembut di bawah kalimah yang tertinggal, garis ambar di bawah kalimah yang dibaca berlainan."},"hear":{"h3":"Dengar kalimahnya","p":"Ketik kalimah yang bertanda dan dengar kalimah itu sahaja daripada bacaan qari sendiri. Kemudian baca semula ayat itu. Tiada markah, selamanya: hanya \u201c2 kalimah untuk diulang\u201d.","youSaid":"Anda membaca","ayahSays":"Ayatnya berbunyi"}},"hifz":{"kicker":"Untuk hafazan","h2":"Uji saya: halaman kekal bertirai sehingga anda membacanya","sub":"Daripada mana-mana pelajaran Hifz, hidupkan Uji saya. Ayat disembunyikan, dan setiap kalimah hanya terbuka apabila anda membacanya dengan betul. Inilah yang paling hampir dengan duduk di hadapan guru anda, pada bila-bila waktu malam.","veilLabel":"Uji saya: kalimah terbuka semasa dibaca"},"muallim":{"kicker":"Akan datang","chip":"Eksperimen","h2":"Mu\u02bfallim: tajwid, diukur dengan rentak anda sendiri","sub1":"Model pendengaran kecil yang kami bina sendiri, di telefon seperti bahagian Tasm\u012b\u02bf yang lain. Ia mengukur setiap mad dan dengung dalam \u1e25arak\u0101t yang dikira daripada bacaan anda sendiri, supaya murattal yang perlahan dan \u1e25adr yang laju dinilai sama, lalu menanda tempat yang akan ditanda guru dengan pensel.","sub2":"Ia bermula dengan mad dan dengung, kemudian qalqalah. Apabila tidak pasti, ia diam: bacaan yang betul tidak sepatutnya ditanda salah. Ia tidak akan menggantikan guru anda; ia membantu anda datang dengan bersedia.","label":"Mu\u02bfallim menanda mad yang dipanjangkan dua harakat sedangkan empat hingga lima diminta","cap":"Mad munfa\u1e63il: dibaca <b>2</b>, sepatutnya <b>4\u20135</b>"},"promise":{"kicker":"Janji kami","h2":"Bacaan anda antara anda dengan Allah","items":[{"b":"Di telefon anda","span":"Tasm\u012b\u02bf mendengar pada peranti itu sendiri. Suara anda tidak pernah dihantar ke mana-mana, walaupun kepada kami."},{"b":"Tidak pernah dirakam","span":"Audio berada dalam memori seketika lalu hilang. Tiada apa yang disimpan."},{"b":"Tanpa internet","span":"Selepas satu muat turun 88 MB, ia berfungsi dalam mod pesawat, di masjid, di mana-mana."},{"b":"Percuma","span":"Tiada langganan, tiada iklan. Sedekah jariah, insya-Allah."}]},"who":{"kicker":"Dibina untuk","h2":"Setiap pembaca, di setiap peringkat","cards":[{"h3":"Pelajar tahfiz","p":"Ulang kaji pelajaran sendiri, tangkap kalimah yang tergelincir, dan datang ke kelas dengan bersedia."},{"h3":"Kanak-kanak","p":"Kalimah emas yang besar, tanda yang lembut, tiada markah. Tidak lama lagi: Qaida, huruf demi huruf, dari Alif hingga Y\u0101."},{"h3":"Pelajar baharu","p":"Membaca seorang diri terasa menggentarkan. Tasm\u012b\u02bf berjalan di sisi anda, ayat demi ayat, mengikut rentak anda."}],"tag":"Qaida tidak lama lagi"},"honest":{"h3":"Ia menyemak kalimah, bukan tajwid","p":"Tasm\u012b\u02bf memberitahu sama ada anda membaca kalimah yang betul mengikut susunan yang betul. Ia tidak menilai makhraj, mad atau hukum tajwid lain, dan ia bukan guru. Sila semak bacaan dengan guru juga. Tasm\u012b\u02bf ditanda Eksperimen sementara kami terus menambah baiknya."},"faq":{"kicker":"Soalan","h2":"Sebelum anda mula","items":[{"q":"Adakah bacaan saya dirakam atau dimuat naik?","a":"Tidak. Pendengaran berlaku sepenuhnya di telefon anda. Audio tidak pernah disimpan dan tidak pernah dihantar, kepada kami atau sesiapa pun."},{"q":"Bolehkah ia berfungsi tanpa internet?","a":"Boleh, setelah pek pendengaran 88 MB berada di telefon anda. Secara lalai ia dimuat turun melalui Wi\u2011Fi; anda boleh memilih data mudah alih."},{"q":"Di telefon apakah ia berfungsi?","a":"iPhone dan telefon Android yang menjalankan Salat-e-Mustaqeem. Pada telefon lama, ia menyesuaikan diri supaya cahaya emasnya tidak ketinggalan."},{"q":"Bolehkah ia menyemak tajwid saya?","a":"Belum, tetapi Mu\u02bfallim sedang dalam perjalanan. Ia akan bermula dengan kadar mad dan dengung, diukur mengikut rentak anda sendiri, dan akan diam setiap kali tidak pasti. Sehingga itu, sila semak tajwid anda dengan guru."},{"q":"Adakah ia sesuai untuk kanak-kanak?","a":"Ya. Tiada markah, hanya tanda yang lembut. Mod Qaida untuk mempelajari huruf akan datang."}]},"final":{"cite":"\u201cDan bacalah Al-Quran dengan tartil.\u201d Al-Muzzammil 73:4","h2":"Mulakan dengan satu ayat malam ini"},"credit":"Model pertuturan Tasm\u012b\u02bf ialah \u201ctilawi-fastconformer-quran\u201d oleh muhdur, berlesen CC BY 4.0, ditala halus daripada FastConformer Arab NVIDIA (CC BY 4.0). Teks Al-Quran: Tanzil."}')}}]);